"""Iterative tree traversal, state meanings, convolution and rerooting."""
from nowcoder_editorials import CONTENT, add, read, reviewed_clone
from nowcoder_tree_support import TREE


def run():
    existing = read(CONTENT / 'reviewed.json')
    def put(n, *args, **kwargs):
        if f'nowcoder-global::{n}' not in existing:
            add(n, *args, **kwargs)
    put(15033, 1300, ['树的重心', '树形动态规划'], '删一个点，最大剩余连通块尽可能小，并列取编号最小。',
        '任取根求子树大小size[u]。删u后，各孩子子树各成一块，父亲方向那块大小为n−size[u]，取这些数最大值作为balance[u]。遍历所有点选择balance最小、编号最小者。迭代建立父亲与遍历顺序，逆序累加大小，避免递归。',
        r'''int n; while (cin >> n) { Tree tree(n); for (int i = 1; i < n; i++) { int a,b; cin >> a >> b; tree.add(a - 1,b - 1); } tree.root(0); vector<int> size(n,1), largest(n); for (int i = n - 1; i >= 0; i--) { int u = tree.order[i]; for (auto [v,w] : tree.edge[u]) if (v != tree.parent[u]) { size[u] += size[v]; largest[u] = max(largest[u],size[v]); } largest[u] = max(largest[u],n - size[u]); } int best = 0; for (int u = 1; u < n; u++) if (largest[u] < largest[best]) best = u; cout << best + 1 << ' ' << largest[best] << '\n'; }''',
        '父亲方向的剩余部分也必须考虑。按编号递增扫描且只在严格更好时更新，就自然保留小编号。', declarations=TREE, complexity=r'每组时间、空间均为 $O(n)$。')
    put(51178, 1400, ['树形动态规划', '独立集'], '员工与直接上司不能同时参加，快乐值可为负，求最大总快乐。',
        '每点维护选、不选两状态。选u时各孩子都不选；不选u时每个孩子独立取两状态较大者。叶子选值等于自己的快乐，不选为0，允许全不选。由无父亲的校长向下遍历，再逆序计算，答案为根两状态最大。',
        r'''int n; cin >> n; vector<long long> happiness(n); for (auto &x : happiness) cin >> x; vector<vector<int>> children(n); vector<int> parent(n,-1); int child,boss; while (cin >> child >> boss && (child || boss)) { child--; boss--; children[boss].push_back(child); parent[child] = boss; } int root = 0; while (parent[root] != -1) root = parent[root]; vector<int> order{root}; for (size_t i = 0; i < order.size(); i++) for (int v : children[order[i]]) order.push_back(v); vector<array<long long,2>> dp(n); for (int i = n - 1; i >= 0; i--) { int u = order[i]; dp[u][1] = happiness[u]; for (int v : children[u]) { dp[u][0] += max(dp[v][0],dp[v][1]); dp[u][1] += dp[v][0]; } } cout << max(dp[root][0],dp[root][1]);''',
        '输入是下属L、上司K，边方向不要反。只禁止直接上司和下属同场，祖孙可以同选。', complexity=r'时间、空间均为 $O(n)$。')
    put(24953, 1800, ['树形动态规划', '最小支配集'], '树上建最少通讯塔，每塔覆盖自己及相邻点，覆盖全部点。',
        '必须区分三个状态：A[u]在u建塔；B[u]不建塔，但由至少一个孩子塔覆盖；C[u]不建且未被孩子覆盖，需要父亲塔。A=1+Σmin(A[v],B[v],C[v])。C要求孩子全为B，否则孩子塔会覆盖u、或孩子需要u建塔。B先对每个孩子取min(A,B)，再补上最小的“强制一个孩子选A”的额外费用。没有孩子时B不可达、C=0、A=1。根不能依赖父亲，所以取min(A[root],B[root])。',
        r'''int n; cin >> n; Tree tree(n); for (int i = 1; i < n; i++) { int a,b; cin >> a >> b; tree.add(a - 1,b - 1); } tree.root(0); const long long inf = 1000000000; vector<array<long long,3>> dp(n); for (int i = n - 1; i >= 0; i--) { int u = tree.order[i]; long long a = 1, b = 0, c = 0, force = inf; for (auto [v,w] : tree.edge[u]) if (v != tree.parent[u]) { a += min({dp[v][0],dp[v][1],dp[v][2]}); long long best = min(dp[v][0],dp[v][1]); b += best; force = min(force,dp[v][0] - best); c = min(inf,c + dp[v][1]); } dp[u] = {a,min(inf,b + force),c}; } cout << min(dp[0][0],dp[0][1]);''',
        '覆盖点与覆盖边不同，不能套用顶点覆盖的两个状态。根没有父亲，不能选“需要父亲覆盖”。', declarations=TREE, complexity=r'时间、空间均为 $O(n)$。')
    if 'nowcoder-global::211219' not in existing:
        reviewed_clone(211219, 24953, '逐项核对中英文Telephone/Cell Phone Network同题；一万结点树，塔覆盖自身及邻点，输入与样例一致。')
    put(51222, 1400, ['树形动态规划', '最小顶点覆盖'], '在树上选最少点，每条边至少一个端点有士兵。',
        '这是覆盖边的最小顶点覆盖。dp[u][0/1]表示u不选或选的最小数：u不选时每个孩子必须选，u选时孩子任选较少的状态。结点编号从0开始，输入每条边只出现一次，先建无向树再任取根处理。',
        r'''int n; while (cin >> n) { Tree tree(n); for (int i = 0; i < n; i++) { int u,k; char colon,open,close; cin >> u >> colon >> open >> k >> close; while (k--) { int v; cin >> v; tree.add(u,v); } } tree.root(0); vector<array<int,2>> dp(n); for (int i = n - 1; i >= 0; i--) { int u = tree.order[i]; dp[u][1] = 1; for (auto [v,w] : tree.edge[u]) if (v != tree.parent[u]) { dp[u][0] += dp[v][1]; dp[u][1] += min(dp[v][0],dp[v][1]); } } cout << min(dp[0][0],dp[0][1]) << '\n'; }''',
        '题目覆盖全部边，孤立单点无需士兵。输入含冒号与括号，可逐字符读取，结点描述顺序不保证根先出现。', declarations=TREE, complexity=r'每组时间、空间均为 $O(n)$。')
    put(202475, 1500, ['树形动态规划', '树上最大路径'], '点权可正可负，求非空简单路径上的最大点权和。',
        'down[u]表示从u向某个后代延伸的最大路径和。孩子中只取最大的正贡献加入u；以u为最高点的完整路径最多连接两个不同孩子，故取最大的两个非负down贡献，再加u权值更新全局答案。全局初值为负无穷，保证全负时仍选一个最大权点，而非空路径。',
        r'''int n; cin >> n; vector<long long> weight(n), down(n); for (auto &x : weight) cin >> x; Tree tree(n); for (int i = 1; i < n; i++) { int a,b; cin >> a >> b; tree.add(a - 1,b - 1); } tree.root(0); long long answer = -(1LL << 60); for (int i = n - 1; i >= 0; i--) { int u = tree.order[i]; long long first = 0, second = 0; for (auto [v,w] : tree.edge[u]) if (v != tree.parent[u]) { long long value = down[v]; if (value > first) { second = first; first = value; } else if (value > second) second = value; } down[u] = weight[u] + first; answer = max(answer,weight[u] + first + second); } cout << answer;''',
        '不是树边权直径，负权下不能用两次找最远点。每个点至多用一次，两条向下支路必须来自不同孩子。', declarations=TREE, complexity=r'时间、空间均为 $O(n)$。')
    put(50505, 1800, ['树形动态规划', '树上背包'], '保留与根连通的指定数量树枝，最大化枝上苹果。',
        'dp[u][j]表示u子树中保留j条边、且保留部分连接u的最大苹果数。初始只留u，j=0值0。合并孩子v时可整棵不取；若取v方向的j条内部边，还必须加连接u、v的边，新增j+1条，贡献dp[v][j]+边权。用新数组按数量卷积，保证每个孩子只合并一次。最后取根的Q边状态。树是否恰好二叉不影响这一写法。',
        r'''int n,q; cin >> n >> q; q = min(q,n - 1); Tree tree(n); for (int i = 1; i < n; i++) { int a,b; long long w; cin >> a >> b >> w; tree.add(a - 1,b - 1,w); } tree.root(0); const long long neg = -(1LL << 60); vector<vector<long long>> dp(n); for (int index = n - 1; index >= 0; index--) { int u = tree.order[index]; dp[u] = {0}; for (auto [v,w] : tree.edge[u]) if (v != tree.parent[u]) { int limit = min(q,(int)dp[u].size() + (int)dp[v].size() - 1); vector<long long> next(limit + 1,neg); for (int i = 0; i < (int)dp[u].size(); i++) { next[i] = max(next[i],dp[u][i]); for (int j = 0; j < (int)dp[v].size() && i + j + 1 <= limit; j++) if (dp[u][i] != neg && dp[v][j] != neg) next[i + j + 1] = max(next[i + j + 1],dp[u][i] + dp[v][j] + w); } dp[u].swap(next); } } cout << dp[0][q];''',
        'Q数的是边，不是点。取孩子的苹果必须先保留父子连接边，不能跨过剪掉的边去取远处高权边。', declarations=TREE, complexity=r'保守时间 $O(nQ^2)$，按实际子树边数限制状态，空间 $O(nQ)$。')
    put(51179, 1800, ['树形动态规划', '依赖背包'], '恰选M门课程，有先修依赖，每课最多一个直接先修，最大化学分。',
        '将没有先修课的课程接到虚拟根0，虚拟根学分0。dp[u][j]表示选u且在其子树共选j门的最大分，初始dp[u][1]=本课学分。逐孩子做数量背包，可选孩子子树0门，或者选择一个包含孩子根的合法状态。中途不能从“不选u”状态接孩子，保证先修必选。处理完后给dp[u][0]=0，供父亲表示整棵不选。目标是dp[0][M+1]，多出的一个是虚拟根。',
        r'''int n,m; cin >> n >> m; vector<vector<int>> children(n + 1); vector<int> credit(n + 1); for (int u = 1; u <= n; u++) { int p; cin >> p >> credit[u]; children[p].push_back(u); } vector<int> order{0}; for (size_t i = 0; i < order.size(); i++) for (int v : children[order[i]]) order.push_back(v); const int neg = -1000000000; int target = m + 1; vector<vector<int>> dp(n + 1); for (int index = n; index >= 0; index--) { int u = order[index]; dp[u] = {0,credit[u]}; for (int v : children[u]) { int cap = min(target,(int)dp[u].size() + (int)dp[v].size() - 2); vector<int> next(cap + 1,neg); next[0] = 0; for (int i = 1; i < (int)dp[u].size(); i++) for (int j = 0; j < (int)dp[v].size() && i + j <= cap; j++) if (dp[u][i] != neg && dp[v][j] != neg) next[i + j] = max(next[i + j],dp[u][i] + dp[v][j]); dp[u].swap(next); } } cout << dp[0][target];''',
        '必须恰好M门，不能直接取至多M的最大值。虚拟根必须算进选课计数后，再把目标改为M+1。', complexity=r'保守时间 $O(nM^2)$，使用实际子树规模限制卷积；空间 $O(nM)$。')
    put(19782, 2100, ['换根动态规划', '乘法原理'], '对每个结点分别统计包含它的连通点集数量，模十亿加七，n至一百万。',
        '固定一棵根树。down[u]表示只在u子树里、包含u的连通集合数。每个孩子方向可以不选，或选一个包含孩子的连通集合，所以down[u]=Π(down[v]+1)。再定义up[u]为父亲方向、包含父亲的连通集合数，则答案为down[u]*(up[u]+1)。给孩子v传递时，up[v]=(up[u]+1)*Π其他孩子(down[child]+1)。\n\n乘积中可能有0，不能用模逆元除掉当前孩子。对每个u的孩子列表建前缀乘积，再从后往前用后缀乘积组合，线性求出所有排除单个孩子的积。树遍历和换根都用迭代，邻接表用连续数组减少百万结点的内存开销。',
        r'''int n; cin >> n; vector<int> head(n,-1), to(max(0,2 * n - 2)), next(to.size()); int edges = 0; auto addEdge = [&](int a, int b) { to[edges] = b; next[edges] = head[a]; head[a] = edges++; }; for (int i = 1; i < n; i++) { int a,b; cin >> a >> b; --a; --b; addEdge(a,b); addEdge(b,a); } vector<int> parent(n,-1), order{0}; parent[0] = 0; order.reserve(n); for (size_t i = 0; i < order.size(); i++) { int u = order[i]; for (int e = head[u]; e != -1; e = next[e]) if (to[e] != parent[u]) { parent[to[e]] = u; order.push_back(to[e]); } } const long long mod = 1000000007; vector<long long> down(n,1), up(n); for (int i = n - 1; i >= 0; i--) { int u = order[i]; for (int e = head[u]; e != -1; e = next[e]) if (to[e] != parent[u]) down[u] = down[u] * (down[to[e]] + 1) % mod; }
        vector<int> children; vector<long long> prefix; for (int u : order) { children.clear(); for (int e = head[u]; e != -1; e = next[e]) if (to[e] != parent[u]) children.push_back(to[e]); prefix.assign(children.size() + 1,1); for (size_t i = 0; i < children.size(); i++) prefix[i + 1] = prefix[i] * (down[children[i]] + 1) % mod; long long suffix = 1; for (int i = (int)children.size() - 1; i >= 0; i--) { int v = children[i]; up[v] = (up[u] + 1) * prefix[i] % mod * suffix % mod; suffix = suffix * (down[v] + 1) % mod; } } for (int u = 0; u < n; u++) cout << down[u] * (up[u] + 1) % mod << '\n';''',
        '每个方向可以整个不选，但只要选就必须包含邻点以保持连通。先把原方向值全部求好，再换根，不能覆盖down原值。', complexity=r'时间、空间均为 $O(n)$。')
    put(22598, 1700, ['树形动态规划', '最小割'], '删除带权树边，让指定点S与所有其他原始叶子断开，最小化删除费用。',
        '备注明确M=N−1且连通，因此实际是树。以S为根，处理孩子v方向有两个选择：切掉父子边，付边权；保留它，则必须在v子树内切断全部原叶子，付dp[v]。取较小值后各方向相加。若v本身就是原始叶子，它没有可在下方切的边，必须直接切父子边，不能误用空子树代价0。指定S即使原度为1也不作为要隔离的终端。',
        r'''int n,m,s; cin >> n >> m >> s; Tree tree(n); while (m--) { int a,b; long long w; cin >> a >> b >> w; tree.add(a - 1,b - 1,w); } tree.root(s - 1); vector<long long> dp(n); for (int i = n - 1; i >= 0; i--) { int u = tree.order[i]; __int128 sum = 0; for (auto [v,w] : tree.edge[u]) if (v != tree.parent[u]) sum += tree.edge[v].size() == 1 ? w : min(w,dp[v]); dp[u] = (long long)min(sum,(__int128)numeric_limits<long long>::max()); } cout << dp[s - 1];''',
        '叶子按删边前的度数定义。边权和可能有较大中间值，内部累加用128位并饱和到64位上界，根答案保证可装入64位。', declarations=TREE, complexity=r'时间、空间均为 $O(n)$。')
    put(24263, 1900, ['换根动态规划', '路径长度'], '选择起始文件夹，使访问全部文件的相对路径字符串长度总和最小。',
        '先从顶层向下，统计每个子树文件数count和从该目录出发访问其子树全部文件的路径长度。走进孩子目录v，会给其全部文件多加len(name[v])+1字符（含斜杠）；孩子是文件则只加文件名长度。根的初始总代价因此可自底向上求得。\n\n把起始目录从u移到孩子目录v：v子树内每个文件都省去name[v]/，共减count[v]*(len[v]+1)；外部文件都要多走../，共加(总文件数−count[v])*3。这个换根式常数时间得到每个目录的全局代价，文件不能作为起始目录。',
        r'''int n; cin >> n; vector<vector<int>> children(n); vector<int> length(n); for (int u = 0; u < n; u++) { string name; int m; cin >> name >> m; length[u] = name.size(); while (m--) { int v; cin >> v; children[u].push_back(v - 1); } } vector<int> order{0}; for (size_t i = 0; i < order.size(); i++) for (int v : children[order[i]]) order.push_back(v); vector<long long> files(n), inside(n), total(n); for (int i = n - 1; i >= 0; i--) { int u = order[i]; if (children[u].empty()) files[u] = 1; else for (int v : children[u]) { files[u] += files[v]; inside[u] += inside[v] + files[v] * (length[v] + !children[v].empty()); } } total[0] = inside[0]; long long answer = total[0]; for (int u : order) if (!children[u].empty()) { answer = min(answer,total[u]); for (int v : children[u]) if (!children[v].empty()) total[v] = total[u] - files[v] * (length[v] + 1) + (files[0] - files[v]) * 3; } cout << answer;''',
        '根目录本身的名字不计入相对路径。文件名后没有斜杠，目录名后有；../固定3字符。总长度用64位。', complexity=r'时间、空间均为 $O(n)$。')
    put(19996, 2200, ['树上背包', '边贡献'], '恰染K个黑点，最大化黑黑距离和加白白距离和。',
        '按边计贡献。孩子子树大小s、其中黑点j时，经过父子边的同色点对数为 j*(K−j)+(s−j)*(N−K−s+j)，乘边长就是这条边对全局距离和的贡献。\n\n树上背包dp[u][j]维护u子树恰有j黑点的最大内部边贡献，合并孩子时枚举其黑点数，把孩子dp及这条边的贡献加进来。子树计数还不能超过全局白点总数，非法状态设负无穷。黑白对称，先将K替成min(K,N−K)可缩小状态。点只初始化成黑或白，边的贡献在合并其下方子树时恰算一次。',
        r'''int n,k; cin >> n >> k; k = min(k,n - k); Tree tree(n); for (int i = 1; i < n; i++) { int a,b; long long w; cin >> a >> b >> w; tree.add(a - 1,b - 1,w); } tree.root(0); const long long neg = -(1LL << 60); vector<int> size(n,1); vector<vector<long long>> dp(n); for (int index = n - 1; index >= 0; index--) { int u = tree.order[index]; dp[u].assign(min(k,1) + 1,0); for (auto [v,w] : tree.edge[u]) if (v != tree.parent[u]) { int cap = min(k,size[u] + size[v]); vector<long long> next(cap + 1,neg); for (int a = 0; a < (int)dp[u].size(); a++) if (dp[u][a] != neg) for (int b = 0; b < (int)dp[v].size() && a + b <= cap; b++) if (dp[v][b] != neg && size[u] + size[v] - a - b <= n - k) { long long white = size[v] - b; long long contribution = (1LL * b * (k - b) + white * (n - k - white)) * w; next[a + b] = max(next[a + b],dp[u][a] + dp[v][b] + contribution); } size[u] += size[v]; dp[u].swap(next); } } cout << dp[0][k];''',
        '只统计同色无序点对，不能把黑白点对算入。贡献公式用全局K与N−K，不能用当前已合并部分代替。', declarations=TREE,
        complexity=r'按实际子树大小做卷积，全部分叉规模乘积合计 $O(n^2)$，时间 $O(n^2)$，空间上界 $O(nK)$。')
    put(20811, 2100, ['树形动态规划', '计数背包'], '删任意树边，所有剩余连通块大小不超过k，统计方案模998244353。',
        'dp[u][s]表示u子树内所有已封闭块都合法，而包含u、还可向父亲连接的块大小为s的方案数。初始只有u，大小1。合并孩子v时：若切边，v的开放块也封闭，其所有大小1到k的方案都可用，保持u块大小不变；若保留边，两开放块合并，大小相加须≤k，方案数相乘。逐孩子用新数组做卷积，所有非u块的合法性由子状态保证。最后根的开放块也封闭，对其全部大小求和。',
        r'''int n,k; cin >> n >> k; k = min(k,n); Tree tree(n); for (int i = 1; i < n; i++) { int a,b; cin >> a >> b; tree.add(a - 1,b - 1); } tree.root(0); const long long mod = 998244353; vector<vector<long long>> dp(n); for (int index = n - 1; index >= 0; index--) { int u = tree.order[index]; dp[u] = {0,1}; for (auto [v,w] : tree.edge[u]) if (v != tree.parent[u]) { long long cutWays = 0; for (long long x : dp[v]) cutWays = (cutWays + x) % mod; int cap = min(k,(int)dp[u].size() + (int)dp[v].size() - 2); vector<long long> next(cap + 1); for (int a = 1; a < (int)dp[u].size(); a++) { next[a] = (next[a] + dp[u][a] * cutWays) % mod; for (int b = 1; b < (int)dp[v].size() && a + b <= cap; b++) next[a + b] = (next[a + b] + dp[u][a] * dp[v][b]) % mod; } dp[u].swap(next); } } long long answer = 0; for (long long x : dp[0]) answer = (answer + x) % mod; cout << answer;''',
        '切边不要求孩子块与u块大小相加≤k；只有保留边才合并大小。每条边两种决策各算一次。', declarations=TREE,
        complexity=r'按实际子树规模限制卷积，总时间 $O(n^2)$，存全部子树表的空间上界 $O(nk)$。')
    put(51180, 1900, ['换根动态规划', '树上最大流'], '每边有容量，节点向其他原始叶子能送出的总流量取最大，求最优源点。',
        '树上不同分支在离开当前点后互不共享边，因此分支流量相加。以任意根求down[u]：通向孩子v的贡献若v是原始叶子，就等于边容量；否则为min(边容量,down[v])，对子节点相加。\n\n换根时，令up[u]为u经父边去父侧终端的可送流量，total[u]=down[u]+up[u]。给孩子v传父侧流量，要从total[u]减去v分支贡献，再与父子边容量取小。例外是u本身原度为1，此时它就是v方向的一个终端，可直接接收全部边容量，不能用删去v后的空和0。遍历所有u的total取最大，源点自身即使是叶子也不接收自己的流。',
        r'''int tests; cin >> tests; while (tests--) { int n; cin >> n; Tree tree(n); for (int i = 1; i < n; i++) { int a,b; long long w; cin >> a >> b >> w; tree.add(a - 1,b - 1,w); } tree.root(0); vector<long long> down(n), up(n); for (int i = n - 1; i >= 0; i--) { int u = tree.order[i]; for (auto [v,w] : tree.edge[u]) if (v != tree.parent[u]) down[u] += tree.edge[v].size() == 1 ? w : min(w,down[v]); } long long answer = 0; for (int u : tree.order) { long long total = down[u] + up[u]; answer = max(answer,total); for (auto [v,w] : tree.edge[u]) if (v != tree.parent[u]) { long long contribution = tree.edge[v].size() == 1 ? w : min(w,down[v]); up[v] = tree.edge[u].size() == 1 ? w : min(w,total - contribution); } } cout << answer << '\n'; }''',
        '叶子身份由原树度数决定，不随计算根变化。两点树两端都为终端，答案为唯一边容量；单点没有其他终端，答案0。', declarations=TREE,
        complexity=r'每组时间、空间均为 $O(n)$。')


